package com.medtrack.tracking.service; import com.medtrack.shared.exception.*; import com.medtrack.shipment.entity.*; import com.medtrack.shipment.repository.ShipmentRepository; import com.medtrack.tracking.dto.*; import com.medtrack.tracking.entity.*; import com.medtrack.tracking.provider.ShipmentTrackingProvider; import com.medtrack.tracking.repository.TrackingEventRepository; import com.medtrack.user.repository.UserRepository; import java.time.Instant; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class TrackingService {private final ShipmentRepository shipments;private final TrackingEventRepository events;private final UserRepository users;private final ShipmentTrackingProvider provider;public TrackingService(ShipmentRepository s,TrackingEventRepository e,UserRepository u,ShipmentTrackingProvider p){shipments=s;events=e;users=u;provider=p;}@Transactional public TrackingResponse record(UUID actor,UUID shipmentId,TrackingEventRequest r){Shipment s=shipments.findById(shipmentId).orElseThrow(()->new NotFoundException("Shipment"));List<TrackingEvent> history=events.findByShipment_IdOrderByEventTimestampAsc(shipmentId);if(!history.isEmpty()&&history.getLast().getMilestoneStatus()==MilestoneStatus.DELIVERED)throw new ConflictException("TRACKING_ALREADY_DELIVERED","Delivered shipment cannot receive further tracking events");TrackingEvent e=events.save(new TrackingEvent(s,r.milestoneStatus(),r.locationName(),r.latitude(),r.longitude(),r.remarks(),r.eventTimestamp()==null?Instant.now():r.eventTimestamp(),users.findById(actor).orElseThrow(()->new NotFoundException("User"))));history.add(e);return new TrackingResponse(shipmentId,history.stream().map(TrackingResponse::of).toList());}@Transactional(readOnly=true) public TrackingResponse history(UUID id){return new TrackingResponse(id,events.findByShipment_IdOrderByEventTimestampAsc(id).stream().map(TrackingResponse::of).toList());}@Transactional public TrackingResponse synchronize(UUID actor,UUID id){TrackingResponse out=null;Shipment s=shipments.findById(id).orElseThrow(()->new NotFoundException("Shipment"));for(TrackingEventRequest r:provider.eventsFor(s))out=record(actor,id,r);return out==null?history(id):out;}}
